# Fix the counting and build final grid
p = [[0]*10 for _ in range(10)]

shift_indices = [6, 5, 4, 3]
test_objs = [
    ('7', 6, 0),   
    ('8', 7, 2),
    ('6', 7, 4),   
    ('3', 8, 7),
]

col_widths = {'7': 2, '8': 2, '6': 1, '3': 2}
obj_heights = {'7': 4, '8': 3, '6': 3, '3': 2}

for i, (color, r0, c_start) in enumerate(test_objs):
    row_shift = shift_indices[i]
    col_shift = 2 * (c_start // 3)
    out_r0 = r0 - row_shift
    out_c0 = c_start - col_shift
    w = col_widths[color]
    h = obj_heights[color]

    for r in range(out_r0, out_r0 + h):
        for c in range(out_c0, out_c0 + w):
            if 0 <= r < 10 and 0 <= c < 10:
                p[r][c] = color

